/**
 * MosaicToast — presentational ephemeral notification
 *
 * Presentational atom. Displays a short-lived status message (success /
 * error / info / warning) with an optional description, an optional
 * host-rendered action, and a required dismiss control. The component
 * performs no network call and owns no SDK / toast-stacking runtime:
 * dismissal is surfaced purely via the `onDismiss()` callback — the host
 * (typically paired with `MosaicToastProvider`) owns the actual queue of
 * visible toasts, their insertion order, and any exit animation.
 *
 * Auto-dismiss is opt-in via `durationMs`: when provided, the component
 * starts a single `setTimeout` on mount and calls `onDismiss()` once it
 * elapses (cleared on unmount / prop change). When `durationMs` is
 * omitted, the toast never dismisses itself — the host's dismiss button
 * (or its own external logic) is the only path to `onDismiss()`.
 *
 * Pattern: MosaicApprovalPrompt.tsx (data-slot, inline cn, React 19 ref
 * prop, displayName, JSDoc, pure variants module).
 * No "use client" in source — prepend-use-client.mjs adds it to dist; the
 * `useEffect` timer below requires the client runtime at use-time.
 * Design tokens: --foreground, --muted-foreground, --border,
 * --destructive, --card, --accent, --background (amber-* utility classes
 * for the "warning" variant, consistent with Tailwind's built-in palette).
 * a11y: the root carries `role="alert"` for the "error" variant (the only
 * variant that represents an unrecoverable failure worth interrupting the
 * screen-reader user for) and `role="status"` for every other variant —
 * both roles are implicitly live regions, so no extra `aria-live` is
 * needed. The dismiss button's accessible name IS the required
 * `dismissAriaLabel` prop — zero hardcoded copy, zero default.
 * Bilingual: every user-facing string (`title`/`description`/
 * `dismissAriaLabel`) is a required-or-explicit caller-supplied prop —
 * the library never generates its own copy.
 *
 * @example
 * <MosaicToast
 *   variant="success"
 *   title="Modifications enregistrées"
 *   description="Vos changements ont été appliqués."
 *   onDismiss={() => removeToast(id)}
 *   dismissAriaLabel="Fermer la notification"
 *   durationMs={5000}
 * />
 */

import type * as React from "react";
import { useEffect } from "react";
import {
  toastCardVariants,
  toastDismissButtonVariants,
  toastTitleVariants,
} from "./toast-variants.js";

// ── Utility ───────────────────────────────────────────────────────────────────

function cn(...classes: (string | undefined | null | false)[]): string {
  return classes.filter(Boolean).join(" ");
}

// ── Types ─────────────────────────────────────────────────────────────────────

/** Visual + semantic tone of the toast. Drives styling AND the a11y role. */
export type MosaicToastVariant = "success" | "error" | "info" | "warning";

export interface MosaicToastProps {
  /** Visual + semantic tone. Drives the a11y role ("alert" for "error", "status" otherwise). */
  variant: MosaicToastVariant;
  /** Toast headline. Required, no default — the library never generates its own copy. */
  title: string;
  /** Optional supporting detail rendered below the title. */
  description?: string;
  /** Host-rendered action region (e.g. an "Undo" button). The library never decides its shape. */
  action?: React.ReactNode;
  /** Called when the toast is dismissed — by the dismiss button OR the `durationMs` timer. */
  onDismiss: () => void;
  /** Accessible name of the dismiss button. Required, no default. */
  dismissAriaLabel: string;
  /** When set, the toast auto-dismisses (`onDismiss()`) after this many milliseconds. */
  durationMs?: number;
  /** Additional Tailwind classes on the root element. */
  className?: string;
  /** React 19 ref prop — forwarded to the root element. */
  ref?: React.Ref<HTMLDivElement>;
}

// ── Component ─────────────────────────────────────────────────────────────────

/**
 * MosaicToast — production ephemeral-notification atom for
 * @vantageos/mosaic-blocks.
 *
 * Purely presentational: renders variant + title + optional description +
 * optional host-rendered action + a required dismiss control, and reports
 * dismissal via `onDismiss()`. No network call, no SDK, no built-in copy,
 * no toast queue / stacking logic (that is `MosaicToastProvider`'s job, or
 * the host's).
 */
export function MosaicToast({
  variant,
  title,
  description,
  action,
  onDismiss,
  dismissAriaLabel,
  durationMs,
  className,
  ref,
}: MosaicToastProps) {
  useEffect(() => {
    if (durationMs === undefined) return;
    const timer = setTimeout(onDismiss, durationMs);
    return () => clearTimeout(timer);
  }, [durationMs, onDismiss]);

  const role = variant === "error" ? "alert" : "status";

  return (
    <div
      ref={ref}
      data-slot="toast"
      role={role}
      className={cn(toastCardVariants({ variant }), className)}
    >
      <div data-slot="toast-body" className="flex min-w-0 flex-1 flex-col gap-1">
        <p data-slot="toast-title" className={toastTitleVariants({ variant })}>
          {title}
        </p>
        {description !== undefined && (
          <p data-slot="toast-description" className="text-sm text-muted-foreground">
            {description}
          </p>
        )}
        {action !== undefined && <div data-slot="toast-action">{action}</div>}
      </div>
      <button
        type="button"
        data-slot="toast-dismiss-button"
        onClick={onDismiss}
        aria-label={dismissAriaLabel}
        className={toastDismissButtonVariants()}
      >
        <svg
          aria-hidden="true"
          viewBox="0 0 24 24"
          width="16"
          height="16"
          fill="none"
          stroke="currentColor"
          strokeWidth="2"
          strokeLinecap="round"
          strokeLinejoin="round"
        >
          <path d="M18 6 6 18" />
          <path d="m6 6 12 12" />
        </svg>
      </button>
    </div>
  );
}

MosaicToast.displayName = "MosaicToast";

/**
 * MosaicToastProvider — presentational fixed-position toast stack container
 *
 * Presentational atom. Anchors a vertical stack of `MosaicToast` elements to
 * one screen corner/edge and stacks them with a fixed gap. It owns no state
 * and no queue: the host renders whichever `MosaicToast` elements are
 * currently visible as `children`, in the order it wants them stacked — this
 * component only positions the resulting stack on screen.
 *
 * Autonomous: does NOT depend on `MosaicToast` itself — any content can be
 * passed as `children`, mirroring the rest of the library's host-controlled
 * composition pattern.
 *
 * Pattern: MosaicApprovalPrompt.tsx (data-slot, inline cn, React 19 ref
 * prop, displayName, JSDoc, pure variants module).
 * No "use client" in source — prepend-use-client.mjs adds it to dist.
 * Design tokens: none directly (the stack itself is unstyled beyond
 * position/spacing) — visual tokens live on the `MosaicToast` children.
 * a11y: the container is `pointer-events-none` so it never intercepts
 * clicks meant for content underneath; each toast re-enables pointer events
 * on itself (native `<button>`/interactive elements are always clickable
 * regardless of an ancestor's `pointer-events: none`... in practice hosts
 * commonly leave toasts non-interactive except for the dismiss button,
 * which still receives events because `pointer-events` do not cascade to
 * elements given their own explicit `pointer-events: auto`; MosaicToast
 * does not set that here, so a host embedding interactive `action` nodes
 * should override `className` on `MosaicToastProvider` if needed).
 * Bilingual: no user-facing copy — the container renders no text of its own.
 */

import type * as React from "react";
import { toastProviderPositionVariants } from "./toast-variants.js";

// ── Utility ───────────────────────────────────────────────────────────────────

function cn(...classes: (string | undefined | null | false)[]): string {
  return classes.filter(Boolean).join(" ");
}

// ── Types ─────────────────────────────────────────────────────────────────────

/** Screen anchor for the toast stack. */
export type MosaicToastProviderPosition =
  | "top-right"
  | "top-center"
  | "bottom-right"
  | "bottom-center";

export interface MosaicToastProviderProps {
  /** The currently visible toasts, host-ordered. */
  children: React.ReactNode;
  /** Screen anchor for the stack. Defaults to "top-right" (a layout default, not visible copy). */
  position?: MosaicToastProviderPosition;
  /** Additional Tailwind classes on the root element. */
  className?: string;
  /** React 19 ref prop — forwarded to the root element. */
  ref?: React.Ref<HTMLDivElement>;
}

// ── Component ─────────────────────────────────────────────────────────────────

/**
 * MosaicToastProvider — production toast-stack positioning atom for
 * @vantageos/mosaic-blocks.
 *
 * Purely presentational: fixes `children` to one screen corner/edge and
 * stacks them with a gap. No state, no queue, no timers — those live on
 * each `MosaicToast` child (`durationMs`) or on the host.
 */
export function MosaicToastProvider({
  children,
  position = "top-right",
  className,
  ref,
}: MosaicToastProviderProps) {
  return (
    <div
      ref={ref}
      data-slot="toast-provider"
      className={cn(toastProviderPositionVariants({ position }), className)}
    >
      {children}
    </div>
  );
}

MosaicToastProvider.displayName = "MosaicToastProvider";

/**
 * toastVariants — pure CVA variant functions for MosaicToast / MosaicToastProvider.
 *
 * Isolated in their own module so they can be re-exported from the
 * `@vantageos/mosaic-blocks/server` subpath without pulling in React.
 *
 * Zero browser / React runtime dependencies — safe in RSC / Node.js.
 */

import { cva } from "class-variance-authority";

/** Root toast card container variants by variant. */
export const toastCardVariants = cva(
  ["flex w-full items-start gap-3 rounded-lg border p-4 shadow-lg sm:max-w-sm"],
  {
    variants: {
      variant: {
        success: "border-border bg-card",
        error: "border-destructive/40 bg-destructive/5",
        info: "border-border bg-card",
        warning: "border-amber-500/40 bg-amber-500/5",
      },
    },
    defaultVariants: {
      variant: "info",
    },
  },
);

/** Title text variants by variant. */
export const toastTitleVariants = cva(["text-sm font-medium"], {
  variants: {
    variant: {
      success: "text-foreground",
      error: "text-destructive",
      info: "text-foreground",
      warning: "text-amber-600 dark:text-amber-400",
    },
  },
  defaultVariants: {
    variant: "info",
  },
});

/** Dismiss button variants — a single visual treatment across every variant. */
export const toastDismissButtonVariants = cva([
  "inline-flex size-6 shrink-0 items-center justify-center rounded-md text-muted-foreground transition-colors hover:bg-accent/50 hover:text-foreground",
]);

/** Provider stack positioning — anchors the toast stack in a screen corner/edge. */
export const toastProviderPositionVariants = cva(
  ["pointer-events-none fixed z-50 flex flex-col gap-2 p-4"],
  {
    variants: {
      position: {
        "top-right": "top-0 right-0 items-end",
        "top-center": "top-0 left-1/2 -translate-x-1/2 items-center",
        "bottom-right": "bottom-0 right-0 items-end",
        "bottom-center": "bottom-0 left-1/2 -translate-x-1/2 items-center",
      },
    },
    defaultVariants: {
      position: "top-right",
    },
  },
);
